"use strict";(self.webpackChunkstrapi_docs=self.webpackChunkstrapi_docs||[]).push([[77205],{33113:e=>{e.exports=JSON.parse('{"tag":{"label":"breaking changes","permalink":"/tags/breaking-changes","allTagsPath":"/tags","count":50,"items":[{"id":"cms/migration/v4-to-v5/breaking-changes/upgrade-to-apollov4","title":"Apollo Server v3 upgraded to Apollo Server v4","description":"The upgrade from Apollo Server v3 to v4 and graphql ^15 to ^16.","permalink":"/cms/migration/v4-to-v5/breaking-changes/upgrade-to-apollov4"},{"id":"cms/migration/v4-to-v5/breaking-changes","title":"Breaking changes","description":"View the list of all breaking changes introduced between Strapi v4 and v5.","permalink":"/cms/migration/v4-to-v5/breaking-changes"},{"id":"cms/migration/v4-to-v5/breaking-changes/publishedat-always-set-when-dandp-disabled","title":"Content types with Draft & Publish disabled always have the publishedAt value set to a date","description":"In Strapi 5, content-types with Draft & Publish disabled always have the publishedAt value set to a date.","permalink":"/cms/migration/v4-to-v5/breaking-changes/publishedat-always-set-when-dandp-disabled"},{"id":"cms/migration/v4-to-v5/breaking-changes/core-service-methods-use-document-service","title":"Core service methods use the Document Service API","description":"In Strapi 5, core service methods use the Document Service API instead of the Entity Service API.","permalink":"/cms/migration/v4-to-v5/breaking-changes/core-service-methods-use-document-service"},{"id":"cms/migration/v4-to-v5/breaking-changes/database-columns","title":"Database columns","description":"Content types always have feature columns","permalink":"/cms/migration/v4-to-v5/breaking-changes/database-columns"},{"id":"cms/migration/v4-to-v5/breaking-changes/database-identifiers-shortened","title":"Database identifiers shortened in v5","description":"Database identifiers are shortened in Strapi v5 and can\'t be longer than 55 characters to avoid issues with identifiers that are too long.","permalink":"/cms/migration/v4-to-v5/breaking-changes/database-identifiers-shortened"},{"id":"cms/migration/v4-to-v5/breaking-changes/lifecycle-hooks-document-service","title":"Database lifecycle hooks are triggered differently with the Document Service API methods","description":"In Strapi 5, database lifecycle hooks are triggered differently with the various Document Service API methods.","permalink":"/cms/migration/v4-to-v5/breaking-changes/lifecycle-hooks-document-service"},{"id":"cms/migration/v4-to-v5/breaking-changes/default-index-removed","title":"defaultIndex removed","description":"In Strapi 5, the \'defaultIndex\' option is removed from the \'public\' middleware.","permalink":"/cms/migration/v4-to-v5/breaking-changes/default-index-removed"},{"id":"cms/migration/v4-to-v5/breaking-changes/do-not-update-repeatable-components-with-document-service-api","title":"defaultIndex removed","description":"In Strapi 5, it\'s not recommended to update repeatable components with the Document Service API","permalink":"/cms/migration/v4-to-v5/breaking-changes/do-not-update-repeatable-components-with-document-service-api"},{"id":"cms/migration/v4-to-v5/breaking-changes/design-system","title":"Design System Updates in Strapi 5","description":"The Strapi Design System has been significantly updated in Strapi 5 with changes to component structure, APIs, and usage patterns.","permalink":"/cms/migration/v4-to-v5/breaking-changes/design-system"},{"id":"cms/migration/v4-to-v5/breaking-changes/use-document-id","title":"documentId should be used instead of id in API calls","description":"Documents should be called by their documentId in Content API calls (REST API & GraphQL).","permalink":"/cms/migration/v4-to-v5/breaking-changes/use-document-id"},{"id":"cms/migration/v4-to-v5/breaking-changes/entity-service-deprecated","title":"Entity Service deprecated","description":"In Strapi 5, the Entity Service API is deprecated in favor of the new Document Service API.","permalink":"/cms/migration/v4-to-v5/breaking-changes/entity-service-deprecated"},{"id":"cms/migration/v4-to-v5/breaking-changes/helper-plugin-deprecated","title":"helper-plugin removed","description":"In Strapi 5, the `helper-plugin` is removed. A whole migration reference is available for plugin developers, and codemods will automatically handle some changes.","permalink":"/cms/migration/v4-to-v5/breaking-changes/helper-plugin-deprecated"},{"id":"cms/migration/v4-to-v5/breaking-changes/inject-content-manager-component","title":"injectContentManagerComponent() removed","description":"In Strapi 5, the Content Manager is a plugin, which affects the injectContentManagerComponent() method, replaced by getPlugin(\'content-manager\').injectComponent().","permalink":"/cms/migration/v4-to-v5/breaking-changes/inject-content-manager-component"},{"id":"cms/migration/v4-to-v5/breaking-changes/i18n-content-manager-locale","title":"Internationalization (i18n)  is now part of the strapi core","description":"Internationalization (i18n) is now part of the Strapi core and no longer a plugin, and this impacts how the locale parameter is sent and accessed.","permalink":"/cms/migration/v4-to-v5/breaking-changes/i18n-content-manager-locale"},{"id":"cms/migration/v4-to-v5/breaking-changes/no-locale-all","title":"locale=all can not be used to query all locales","description":"In Strapi 5, it\'s no longer possible to get all localized versions with the \'?locale=all\' parameter.","permalink":"/cms/migration/v4-to-v5/breaking-changes/no-locale-all"},{"id":"cms/migration/v4-to-v5/breaking-changes/license-only","title":"lockIcon replaced by licenseOnly","description":"In Strapi 5, the lockIcon property is replaced by licenseOnly, which affects how the addMenuLink(), addSettingsLink(), and addSettingsLinks() methods from the Admin Panel API work.","permalink":"/cms/migration/v4-to-v5/breaking-changes/license-only"},{"id":"cms/migration/v4-to-v5/breaking-changes/model-config-path-uses-uid","title":"Model config path uses uid instead of dot notation","description":"Modules like `api::myapi` and `plugin::upload` should no longer be accessed in the Strapi config using `api.myapi` and `plugin.upload`, but instead using `api::myapi` and `plugin::upload`.","permalink":"/cms/migration/v4-to-v5/breaking-changes/model-config-path-uses-uid"},{"id":"cms/migration/v4-to-v5/breaking-changes/mysql5-unsupported","title":"MySQL v5 unsupported","description":"MySQL v5 is not supported in Strapi v5 anymore.","permalink":"/cms/migration/v4-to-v5/breaking-changes/mysql5-unsupported"},{"id":"cms/migration/v4-to-v5/breaking-changes/no-find-page-in-document-service","title":"No findPage() in Document Service API","description":"In Strapi 5, the Entity Service API is deprecated, and for the findPage() method you should use the Document Service API\'s findMany() method instead.","permalink":"/cms/migration/v4-to-v5/breaking-changes/no-find-page-in-document-service"},{"id":"cms/migration/v4-to-v5/breaking-changes/no-shared-population-strategy-components-dynamic-zones","title":"No shared population strategy for components & dynamic zones","description":"In Strapi 5, the shared population strategy is not supported anymore, so components and dynamic zones must be explicitly populated using `on` fragments.","permalink":"/cms/migration/v4-to-v5/breaking-changes/no-shared-population-strategy-components-dynamic-zones"},{"id":"cms/migration/v4-to-v5/breaking-changes/only-better-sqlite3-for-sqlite","title":"Only the `better-sqlite3` package is supported for the SQLite client","description":"In Strapi 5, users can only use the `better-sqlite3` package for SQLite databases, and the `client` value for it must be set to `sqlite`.","permalink":"/cms/migration/v4-to-v5/breaking-changes/only-better-sqlite3-for-sqlite"},{"id":"cms/migration/v4-to-v5/breaking-changes/publication-state-removed","title":"publicationState is removed and replaced by status","description":"In Strapi 5, \'publicationState\' can no longer be used in Content API calls. The new status parameter can be used and accepts 2 different values, draft and published.","permalink":"/cms/migration/v4-to-v5/breaking-changes/publication-state-removed"},{"id":"cms/migration/v4-to-v5/breaking-changes/attributes-and-content-types-names-reserved","title":"Reserved attributes and content-types names","description":"In Strapi 5, some attributes and content types names are reserved, and all fields or content types using the reserved names should be renamed before migrating to prevent data loss.","permalink":"/cms/migration/v4-to-v5/breaking-changes/attributes-and-content-types-names-reserved"},{"id":"cms/migration/v4-to-v5/breaking-changes/default-input-validation","title":"REST API input is validated by default in controllers","description":"In Strapi 5, REST API input is validated by default in controllers, instead of accepting invalid data and sanitizing it silently.","permalink":"/cms/migration/v4-to-v5/breaking-changes/default-input-validation"},{"id":"cms/migration/v4-to-v5/breaking-changes/server-default-log-level","title":"Server log level is `http`","description":"The default log level of the middleware logger in Strapi 5 is \'http\'.","permalink":"/cms/migration/v4-to-v5/breaking-changes/server-default-log-level"},{"id":"cms/migration/v4-to-v5/breaking-changes/server-proxy","title":"Server proxy configuration","description":"In Strapi 5, all proxy configuration options are now configured through the \'server.proxy\' object in the \'/config/server.js|ts\' instead of having various option names such as \'globalProxy\' and \'proxy\' in Strapi v4.","permalink":"/cms/migration/v4-to-v5/breaking-changes/server-proxy"},{"id":"cms/migration/v4-to-v5/breaking-changes/removed-support-for-some-env-options","title":"Some env-only configuration options are handled by the server configuration","description":"In Strapi 5, some env-only configuration options are handled by the server configuration","permalink":"/cms/migration/v4-to-v5/breaking-changes/removed-support-for-some-env-options"},{"id":"cms/migration/v4-to-v5/breaking-changes/mailgun-provider-variables","title":"Some Mailgun provider legacy variables are not supported","description":"In Strapi 5, some variables have been renamed for the Mailgun provider options, dropping support for some legacy variables that were deprecated in Strapi v4.","permalink":"/cms/migration/v4-to-v5/breaking-changes/mailgun-provider-variables"},{"id":"cms/migration/v4-to-v5/breaking-changes/sort-by-id","title":"Sorting by id is no longer possible to sort by chronological order","description":"In Strapi 5, sorting by id is no longer possible to sort by chronological order, and you should use createdAt instead.","permalink":"/cms/migration/v4-to-v5/breaking-changes/sort-by-id"},{"id":"cms/migration/v4-to-v5/step-by-step","title":"Step-by-step guide to upgrade to Strapi 5","description":"Follow this step-by-step guide to upgrade from Strapi v4 to Strapi 5","permalink":"/cms/migration/v4-to-v5/step-by-step"},{"id":"cms/migration/v4-to-v5/breaking-changes/new-response-format","title":"Strapi 5 has a new, flattened response format for API calls","description":"In Strapi 5, the response format has been simplified and flattened, and attributes of requested content are no longer wrapped in an attributes object.","permalink":"/cms/migration/v4-to-v5/breaking-changes/new-response-format"},{"id":"cms/migration/v4-to-v5/breaking-changes/koa-body-v6","title":"Strapi 5 uses koa-body v6","description":"Strapi 5 uses koa-body v6, which updates node formidable to v2.","permalink":"/cms/migration/v4-to-v5/breaking-changes/koa-body-v6"},{"id":"cms/migration/v4-to-v5/breaking-changes/react-router-dom-6","title":"Strapi 5 uses React Router DOM 6","description":"Strapi 5 uses react-router-dom v6. This impacts the links added to Global Settings or to the Menu using the Admin Panel API.","permalink":"/cms/migration/v4-to-v5/breaking-changes/react-router-dom-6"},{"id":"cms/migration/v4-to-v5/breaking-changes/strapi-utils-refactored","title":"strapi-utils is refactored","description":"In Strapi 5, the \'strapi-utils\' core package has been refactored. This page lists the additions, removals, and other updates.","permalink":"/cms/migration/v4-to-v5/breaking-changes/strapi-utils-refactored"},{"id":"cms/migration/v4-to-v5/breaking-changes/fetch","title":"strapi.fetch uses native fetch() API","description":"In Strapi 5, the `strapi.fetch` object is now wrapping node Fetch API instead of node-fetch.","permalink":"/cms/migration/v4-to-v5/breaking-changes/fetch"},{"id":"cms/migration/v4-to-v5/breaking-changes/strict-requirements-config-files","title":"Strict requirements for configuration filenames","description":"Strapi 5 has strict requirements on the configuration filenames allowed to be loaded.","permalink":"/cms/migration/v4-to-v5/breaking-changes/strict-requirements-config-files"},{"id":"cms/migration/v4-to-v5/breaking-changes/templates","title":"Templates are now regular, standalone Strapi applications","description":"Templates have been fully rewritten in Strapi 5 and now are standalone, regular Strapi applications, making it easier to create, distribute, and re-use them.","permalink":"/cms/migration/v4-to-v5/breaking-changes/templates"},{"id":"cms/migration/v4-to-v5/breaking-changes/remove-webhook-populate-relations","title":"The \'webhooks.populateRelations\' server configuration is removed","description":"In Strapi 5, webhooks have been refactored and the `webhook.populateRelations` option will become redundant. This might affect lifecycles expecting the returned relations of create, update and delete to be populated.","permalink":"/cms/migration/v4-to-v5/breaking-changes/remove-webhook-populate-relations"},{"id":"cms/migration/v4-to-v5/breaking-changes/edit-view-layout-and-list-view-layout-rewritten","title":"The `EditViewLayout` and `ListViewLayout` have been rewritten","description":"In Strapi 5, some admin panel hooks have been removed from the Redux store and a new `useDocumentLayout` hook is introduced.","permalink":"/cms/migration/v4-to-v5/breaking-changes/edit-view-layout-and-list-view-layout-rewritten"},{"id":"cms/migration/v4-to-v5/breaking-changes/admin-panel-rbac-store-updated","title":"The admin panel RBAC system has been updated","description":"In Strapi 5, there is no `content-manager_rbacManager` anymore, and the regular permissions system is used instead.","permalink":"/cms/migration/v4-to-v5/breaking-changes/admin-panel-rbac-store-updated"},{"id":"cms/migration/v4-to-v5/breaking-changes/yarn-not-default","title":"The CLI default package manager is not yarn anymore","description":"Strapi 5 detects what package manager you are using to run the CLI, and uses this package manager to install dependencies.","permalink":"/cms/migration/v4-to-v5/breaking-changes/yarn-not-default"},{"id":"cms/migration/v4-to-v5/breaking-changes/redux-content-manager-app-state","title":"The ContentManagerAppState redux is modified","description":"In Strapi 5, the redux store for the Content Manager has been changed and some redux actions were removed.","permalink":"/cms/migration/v4-to-v5/breaking-changes/redux-content-manager-app-state"},{"id":"cms/migration/v4-to-v5/breaking-changes/get-where-removed","title":"The getWhere() method for permission provider instances has been removed","description":"In Strapi 5, the getWhere() for permission provider instances has been removed, and users should use provider.values().filter() to replace it.","permalink":"/cms/migration/v4-to-v5/breaking-changes/get-where-removed"},{"id":"cms/migration/v4-to-v5/breaking-changes/graphql-api-updated","title":"The GraphQL API has been updated","description":"In Strapi 5, the GraphQL API has been updated. It handles the new, flattened response format, and can also now accept Relay-style queries.","permalink":"/cms/migration/v4-to-v5/breaking-changes/graphql-api-updated"},{"id":"cms/migration/v4-to-v5/breaking-changes/is-supported-image-removed","title":"The isSupportedImage method is removed in Strapi 5","description":"The `isSupportedImage` method is removed in Strapi 5. Users should use `isImage` or `isOptimizableImage` instead.","permalink":"/cms/migration/v4-to-v5/breaking-changes/is-supported-image-removed"},{"id":"cms/migration/v4-to-v5/breaking-changes/register-allowed-fields","title":"The Users & Permissions plugin\'s register.allowedFields configuration option defaults to []","description":"In Strapi 5, The Users & Permissions plugin\'s `register.allowedFields` configuration option defaults to [].","permalink":"/cms/migration/v4-to-v5/breaking-changes/register-allowed-fields"},{"id":"cms/migration/v4-to-v5/breaking-changes/no-upload-at-entry-creation","title":"Upload a file at entry creation no longer supported","description":"In Strapi 5, it is not possible to upload a file while creating an entry, so users must upload the file first, and then create the entry with the created file id.","permalink":"/cms/migration/v4-to-v5/breaking-changes/no-upload-at-entry-creation"},{"id":"cms/migration/v4-to-v5/breaking-changes/vite","title":"Vite is the default bundler","description":"In Strapi 5, Vite is the default bundler and replaces webpack.","permalink":"/cms/migration/v4-to-v5/breaking-changes/vite"},{"id":"cms/migration/v4-to-v5/breaking-changes/webpack-aliases-removed","title":"Webpack Aliases are removed","description":"A simplified approach of aliasing in Strapi v5.","permalink":"/cms/migration/v4-to-v5/breaking-changes/webpack-aliases-removed"}],"unlisted":false}}')}}]);